//! What every media adapter does with an upstream answer (`upstream-error.mjs`, and the pure parts
//! of `download.mjs`): a failed response becomes one legible sentence with a code and status, a
//! subscription usage limit is told apart from rate limiting, generated bytes are decoded from
//! base64 the way `Buffer.from(x, 'base64')` does, and a Veo download address is accepted only
//! from Google's file host.

use std::sync::LazyLock;

use base64::Engine as _;
use base64::alphabet;
use base64::engine::general_purpose::{GeneralPurpose, NO_PAD};
use mixdog_js::{js_trim, slice_utf16, to_number, value_to_string};
use regex::Regex;
use serde_json::Value;

use super::lanes::LaneError;

pub const MAX_GENERATED_MEDIA_BYTES: usize = 256 * 1024 * 1024;
const MAX_GENERATED_MEDIA_BASE64_CHARS: usize = MAX_GENERATED_MEDIA_BYTES.div_ceil(3) * 4 + 4;

fn media_error(message: String, code: &'static str, status: u16) -> LaneError {
    LaneError { message, code, status }
}

fn rx(pattern: &str) -> Regex {
    Regex::new(pattern).expect("a static pattern")
}

fn truthy(value: Option<&Value>) -> bool {
    match value {
        None | Some(Value::Null) => false,
        Some(Value::Bool(b)) => *b,
        Some(Value::Number(n)) => n.as_f64().is_some_and(|n| n != 0.0 && !n.is_nan()),
        Some(Value::String(s)) => !s.is_empty(),
        Some(_) => true,
    }
}

/// `reason(text)`: the provider's own sentence, when its body is JSON that has one.
fn reason(text: &str) -> String {
    let Ok(parsed) = serde_json::from_str::<Value>(text) else { return String::new() };
    let nested = parsed.get("error").and_then(|e| e.get("message"));
    let chosen = [nested, parsed.get("error"), parsed.get("message")].into_iter().find(|v| truthy(*v)).flatten();
    chosen.and_then(Value::as_str).unwrap_or_default().to_owned()
}

/// Raw bodies are echoed only when they are short plain text; HTML error pages never reach the Studio.
fn raw_detail(text: &str) -> String {
    let raw = js_trim(text);
    if raw.is_empty() || raw.starts_with('<') { String::new() } else { slice_utf16(raw, 300) }
}

/// `upstreamError(label, status, text)`: the error a lane throws for a non-OK upstream response.
pub fn upstream_error(label: &str, status: u16, text: &str) -> LaneError {
    static CREDIT_HINTS: LazyLock<Regex> = LazyLock::new(|| rx(r"(?i)credit|spending limit|billing|quota|insufficient|payment"));
    let mut detail = reason(text);
    if detail.is_empty() {
        detail = raw_detail(text);
    }
    let credit = CREDIT_HINTS.is_match(&detail);
    if status == 401 || status == 403 {
        if credit {
            return media_error(format!("{label}: account has no usable balance — {detail}"), "MEDIA_BILLING_BLOCKED", status);
        }
        return media_error(format!("{label}: authentication rejected — sign in again in Settings → Providers"), "MEDIA_AUTH_REJECTED", status);
    }
    if status == 402 || credit {
        return media_error(format!("{label}: account has no usable balance — {detail}"), "MEDIA_BILLING_BLOCKED", if status == 0 { 402 } else { status });
    }
    if status == 429 {
        return media_error(format!("{label}: rate limited — retry in a moment"), "MEDIA_RATE_LIMITED", 429);
    }
    let tail = if detail.is_empty() { String::new() } else { format!(": {detail}") };
    media_error(format!("{label} failed ({status}){tail}"), "MEDIA_UPSTREAM_FAILED", status)
}

/// Response headers, looked up without regard to case.
pub struct Headers<'a>(pub &'a [(String, String)]);

impl Headers<'_> {
    fn get(&self, name: &str) -> String {
        self.0.iter().find(|(key, _)| key.eq_ignore_ascii_case(name)).map(|(_, value)| js_trim(value).to_owned()).unwrap_or_default()
    }
}

/// `epochSeconds`: a positive finite number, truncated; else 0.
fn epoch_seconds(value: &Value) -> i64 {
    let number = to_number(value);
    if number.is_finite() && number > 0.0 { number.trunc() as i64 } else { 0 }
}

fn epoch_seconds_text(text: &str) -> i64 {
    epoch_seconds(&Value::String(text.to_owned()))
}

/// The latest reset among the exhausted windows the rate-limit headers advertise.
fn header_reset_at(headers: &Headers<'_>, limit_id: &str) -> Option<i64> {
    let mut families = Vec::new();
    if !limit_id.is_empty() {
        families.push(format!("x-{}", limit_id.to_lowercase().replace('_', "-")));
    }
    if !families.iter().any(|f| f == "x-codex") {
        families.push("x-codex".to_owned());
    }
    let mut latest = 0;
    for family in families {
        for window in ["primary", "secondary"] {
            let used = to_number(&Value::String(headers.get(&format!("{family}-{window}-used-percent"))));
            let reset_at = epoch_seconds_text(&headers.get(&format!("{family}-{window}-reset-at")));
            if used >= 100.0 && reset_at > latest {
                latest = reset_at;
            }
        }
    }
    (latest != 0).then_some(latest)
}

/// `{ limitId, resetsAt }` of a subscription usage-limit failure.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct UsageLimit {
    pub limit_id: String,
    pub resets_at: Option<i64>,
}

/// `usageLimitInfo(error, headers)`; `error` is the upstream error object (`{ type, code,
/// resets_at }`) from an HTTP body or a stream event.
pub fn usage_limit_info(error: &Value, headers: &Headers<'_>) -> Option<UsageLimit> {
    static USAGE_LIMIT: LazyLock<Regex> = LazyLock::new(|| rx(r"(?i)usage_?limit"));
    let reached = headers.get("x-codex-rate-limit-reached-type");
    let kinds = [error.get("type").and_then(Value::as_str), error.get("code").and_then(Value::as_str), Some(reached.as_str())];
    if !kinds.into_iter().flatten().any(|kind| USAGE_LIMIT.is_match(kind)) {
        return None;
    }
    let active = headers.get("x-codex-active-limit");
    let limit_id = if !active.is_empty() {
        active
    } else {
        [error.get("limit_id"), error.get("metered_feature")].into_iter().find(|v| truthy(*v)).flatten().map(value_to_string).unwrap_or_default()
    };
    let stated = error.get("resets_at").map_or(0, epoch_seconds);
    let resets_at = if stated != 0 { Some(stated) } else { header_reset_at(headers, &limit_id) };
    Some(UsageLimit { limit_id, resets_at })
}

/// `usageLimitFromResponse(status, text, headers)`: only 429s are usage limits.
pub fn usage_limit_from_response(status: u16, text: &str, headers: &Headers<'_>) -> Option<UsageLimit> {
    if status != 429 {
        return None;
    }
    let parsed = serde_json::from_str::<Value>(text).unwrap_or(Value::Null);
    let error = match parsed.get("error") {
        Some(inner) if inner.is_object() || inner.is_array() => inner,
        _ => &parsed,
    };
    usage_limit_info(error, headers)
}

fn format_reset_at(seconds: i64) -> String {
    let at = chrono::DateTime::from_timestamp(seconds, 0).unwrap_or_default();
    format!("{} UTC", at.format("%Y-%m-%d %H:%M"))
}

/// The error a lane throws when the subscription's usage window is exhausted, and when it resets.
pub fn usage_limit_error(label: &str, limit: &UsageLimit) -> (LaneError, Option<String>) {
    static IMAGE: LazyLock<Regex> = LazyLock::new(|| rx(r"(?i)image"));
    let what = if IMAGE.is_match(&limit.limit_id) { "image generation usage limit reached" } else { "usage limit reached" };
    let when = limit.resets_at.map_or_else(|| "try again after the usage window resets".to_owned(), |at| format!("resets {}", format_reset_at(at)));
    let resets = limit.resets_at.map(|at| chrono::DateTime::from_timestamp(at, 0).unwrap_or_default().to_rfc3339_opts(chrono::SecondsFormat::Millis, true));
    (media_error(format!("{label}: {what} — {when}"), "MEDIA_USAGE_LIMIT", 429), resets)
}

/// `Buffer.from(text, 'base64')`: both alphabets, whitespace and stray characters skipped, the
/// first `=` ends the data, a lone trailing character carries no byte.
pub fn node_base64(text: &str) -> Vec<u8> {
    let mut clean = String::new();
    for c in text.chars() {
        match c {
            '=' => break,
            '-' => clean.push('+'),
            '_' => clean.push('/'),
            c if c.is_ascii_alphanumeric() || c == '+' || c == '/' => clean.push(c),
            _ => {}
        }
    }
    if clean.len() % 4 == 1 {
        clean.pop();
    }
    NODE_BASE64.decode(clean).unwrap_or_default()
}

/// Unpadded, and the bits left over after the last whole byte are dropped whatever they are
/// (`"ab"` is `0x69`), as Node's decoder drops them.
const NODE_BASE64: GeneralPurpose = GeneralPurpose::new(&alphabet::STANDARD, NO_PAD.with_decode_allow_trailing_bits(true));

/// `decodeBase64Media(value, label)`.
pub fn decode_base64_media(value: &Value, label: &str) -> Result<Vec<u8>, LaneError> {
    let too_large = || media_error(format!("{label} exceeds the media size limit"), "MEDIA_RESULT_TOO_LARGE", 502);
    let Some(text) = value.as_str().filter(|t| !t.is_empty() && t.encode_utf16().count() <= MAX_GENERATED_MEDIA_BASE64_CHARS) else { return Err(too_large()) };
    let bytes = node_base64(text);
    if bytes.is_empty() || bytes.len() > MAX_GENERATED_MEDIA_BYTES {
        return Err(too_large());
    }
    Ok(bytes)
}

/// `geminiMediaDownloadUrl(input)`: only an `https` address on Google's file host, without
/// credentials, with `alt=media` set.
pub fn gemini_media_download_url(input: &Value) -> Result<String, LaneError> {
    let text = if truthy(Some(input)) { value_to_string(input) } else { String::new() };
    let Ok(mut url) = reqwest::Url::parse(&text) else {
        return Err(media_error("Veo returned an invalid video URI".to_owned(), "MEDIA_UPSTREAM_FAILED", 502));
    };
    let trusted = url.scheme() == "https" && url.host_str().is_some_and(|host| host.eq_ignore_ascii_case("generativelanguage.googleapis.com")) && url.username().is_empty() && url.password().is_none();
    if !trusted {
        return Err(media_error("Veo returned an untrusted video URI".to_owned(), "MEDIA_UPSTREAM_FAILED", 502));
    }
    // `searchParams.set('alt', 'media')`: the first `alt` is replaced, others dropped, and the
    // whole query is written back in form-urlencoded form.
    let mut pairs: Vec<(String, String)> = url.query_pairs().map(|(k, v)| (k.into_owned(), v.into_owned())).collect();
    match pairs.iter().position(|(key, _)| key == "alt") {
        Some(at) => {
            pairs[at].1 = "media".to_owned();
            let mut seen = false;
            pairs.retain(|(key, _)| key != "alt" || !std::mem::replace(&mut seen, true));
        }
        None => pairs.push(("alt".to_owned(), "media".to_owned())),
    }
    url.query_pairs_mut().clear().extend_pairs(pairs);
    Ok(url.to_string())
}
